}
const ia = r.ia;
if (ia.intencion === 'INCIDENCIA' && textoLimpio.length < 12) ia.intencion = 'CONVERSACION';
if (ia.intencion === 'CONVERSACION' || ia.intencion === 'FUERA_DE_ALCANCE') ia.incidencia = { ...VACIA };
// «¿Puedo reservar…?», «mira si…», «dime si…» son preguntas: se responde la disponibilidad, no se intenta reservar.
if (ia.intencion === 'RESERVA' && /(?:^| )(puedo|podria|se puede|mira si|dime si|revisa si|verifica si|hay espacio|esta libre|esta ocupad)/.test(textoLimpio)) ia.intencion = 'CONSULTA';
// Día del pedido: lo que mande el formulario manda; luego "mañana"/"pasado mañana" del texto (determinista; "de la mañana" no cuenta);
// luego la fecha que interpretó la IA; si nadie la dice, hoy.
const sumarDias = (iso, n) => new Date(Date.parse(`${iso}T12:00:00-05:00`) + n * 86400e3 - BOGOTA).toISOString().slice(0, 10);
const relativo = (() => {
  const t = norm(req.reporte);
