}
const texto = extraerDelTexto(req.reporte);

const pedido = {
  sala: salaPorNombre(req.salaActual) || salaPorNombre(ia.sala),
  inicio: req.horaInicio || ia.horaInicio || texto.inicio,
  fin: req.horaFinSolicitada || ia.horaFin || texto.fin,
  asistentes: req.asistentes ?? ia.asistentes ?? texto.asistentes,
};
const intervalo = () => (pedido.inicio && pedido.fin ? { s: aFecha(pedido.inicio), e: aFecha(pedido.fin) } : null);
const NO_ES_SALA = new Set(['libre', 'libres', 'disponible', 'disponibles', 'ocupada', 'ocupadas', 'reservada', 'para', 'de', 'del', 'que', 'hoy', 'manana', 'mas', 'grande', 'grandes', 'pequena', 'pequenas', 'el', 'la', 'una', 'un', 'con', 'donde', 'cual', 'a', 'en', 'por', 'y', 'o']);
const salaDesconocida = (() => {
  if (pedido.sala) return null;
  const m = norm(req.reporte).match(/\bsala\s+([a-z0-9]+)/);
  if (!m || NO_ES_SALA.has(m[1]) || salas.some((s) => norm(s.nombre) === m[1])) return null;
  return m[1].charAt(0).toUpperCase() + m[1].slice(1);
})();

// Salas aptas (estado, aforo y sin cruce) sobre una vista de reservas; menor aforo suficiente primero.
function libres(iv, asistentes, vista, excluir = []) {
  return salas
    .filter((s) => s.estado === 'DISPONIBLE' && s.capacidad >= asistentes && !excluir.includes(s.nombre)
      && !vista.some((b) => b.sala === s.nombre && cruzan(b, iv)))
    .sort((a, b) => a.capacidad - b.capacidad || a.nombre.localeCompare(b.nombre));
}
const nombres = (l) => l.slice(0, 3).map((s) => `${s.nombre} (${s.capacidad})`).join(', ');
const rango = (iv) => `${hhmm(iv.s)} a ${hhmm(iv.e)}`;

// Reubica una reserva a la sala libre más ajustada; devuelve la sala o null.
function reubicar(b, vista, excluir) {
  const dest = libres(b, b.asistentes, vista.filter((o) => o.id !== b.id), [b.sala, ...excluir])[0];
  if (!dest) return null;
  b.sala = dest.nombre;
  return dest;
}

function reservar() {
  const iv = intervalo();
  const faltan = [!pedido.inicio && 'la hora de inicio', !pedido.fin && 'la hora de fin', !pedido.asistentes && 'el número de asistentes'].filter(Boolean);
  if (!iv || !pedido.asistentes) return fin('Faltan datos para reservar', `Me falta ${faltan.join(', ').replace(/, ([^,]*)$/, ' y $1')}. Envía la solicitud completa en un solo mensaje, por ejemplo: "Reserva la sala Azul hoy de 3 a 5 pm para 2 personas".`, 'WARNING', 'NINGUNA');
  // Si el texto trae un horario invertido («de 5 pm a 3 pm») no se corrige en silencio.
  if (iv.e <= iv.s || (!req.horaInicio && texto.inicio && texto.fin && texto.fin <= texto.inicio)) return fin('Horario inválido', 'La hora de fin debe ser posterior a la de inicio. Revisa el horario, por ejemplo: «de 3 a 5 pm».', 'WARNING', 'SOLICITUD_RECHAZADA');
  if (iv.s < new Date(ahora.getTime() - 15 * 60e3)) return fin('Horario pasado', `Esa hora ya pasó (son las ${hhmm(ahora)}). Indica una hora futura.`, 'WARNING', 'SOLICITUD_RECHAZADA');
  let sala = pedido.sala;
  if (!sala) {
    sala = libres(iv, pedido.asistentes, reservas)[0];
    if (!sala) return fin('Sin salas disponibles', `Ninguna sala libre admite ${pedido.asistentes} personas ${diaTxt()} de ${rango(iv)}.`, 'WARNING', 'SOLICITUD_RECHAZADA');
  } else {
    const alt = libres(iv, pedido.asistentes, reservas, [sala.nombre]);
    const sugerencia = alt.length ? ` Alternativas: ${nombres(alt)}.` : '';
    const detalle = { tipo: 'ALTERNATIVAS', salas: alt.slice(0, 3).map((s) => ({ nombre: s.nombre, capacidad: s.capacidad })) };
    if (sala.estado !== 'DISPONIBLE') return fin('Sala no disponible', `${sala.nombre} está en ${sala.estado.toLowerCase()}.${sugerencia}`, 'WARNING', 'SOLICITUD_RECHAZADA', { detalle });
    if (pedido.asistentes > sala.capacidad) return fin('Aforo excedido', `${sala.nombre} admite ${sala.capacidad} personas y se solicitaron ${pedido.asistentes}.${sugerencia}`, 'WARNING', 'SOLICITUD_RECHAZADA', { detalle });
    const choque = reservas.find((b) => b.sala === sala.nombre && cruzan(b, iv));
