  }
  return fin('Reserva confirmada', `${sala.nombre} reservada${quien ? ` para ${quien}` : ''} ${diaTxt()} de ${rango(iv)} (${pedido.asistentes} personas).`, 'SUCCESS', 'RESERVA_CREADA', {
