    detalle: { tipo: 'RESERVA', sala: sala.nombre, capacidad: sala.capacidad, inicio: iv.s.toISOString(), fin: iv.e.toISOString(), asistentes: pedido.asistentes },
    ops: [{ op: 'insert', sala: sala.nombre, ocupante: req.usuario, rol: req.rol, inicio: iv.s.toISOString(), fin: iv.e.toISOString(), asistentes: pedido.asistentes, origen: req.canal.toUpperCase() }],
