  const ref = pedido.inicio ? aFecha(pedido.inicio) : ahora;
  const objetivo = mias.find((b) => b.s <= ref && ref < b.e) || mias.sort((a, b) => b.e - a.e)[0];
  if (!objetivo) return fin('No hay reserva para extender', `No encontré una reserva activa a ${quien ? `nombre de ${quien}` : 'tu nombre'}${pedido.sala ? ` en ${pedido.sala.nombre}` : ''}.`, 'WARNING', 'SOLICITUD_RECHAZADA');
  const nuevoFin = aFecha(pedido.fin);
  if (nuevoFin <= objetivo.s) return fin('Horario inválido', 'La nueva hora de fin debe ser posterior al inicio de la reserva.', 'WARNING', 'SOLICITUD_RECHAZADA');
  const tocadas = [{ sala: objetivo.sala, ocupante: objetivo.ocupante }];
  const op = { op: 'extend', id: objetivo.id, fin: nuevoFin.toISOString(), nota: 'Horario extendido por orden de llegada' };
  if (nuevoFin <= objetivo.e) {
    op.nota = 'Horario ajustado';
    return fin('Horario ajustado', `${objetivo.sala} queda reservada hasta las ${hhmm(nuevoFin)}.`, 'SUCCESS', 'EXTENSION_APLICADA', { refInicio: objetivo.s.toISOString(), tocadas, ops: [op] });
  }
  const nuevo = { s: objetivo.s, e: nuevoFin };
  const choques = reservas.filter((b) => b.id !== objetivo.id && b.sala === objetivo.sala && cruzan(b, nuevo)).sort((a, b) => a.creada - b.creada);
  const vista = reservas.map((b) => ({ ...b }));
  const ops = [];
  const movidos = [];
  for (const c of choques) {
    if (c.creada < objetivo.creada) return fin('Extensión rechazada', `${c.ocupante} reservó ${objetivo.sala} antes (de ${rango(c)}) y conserva el espacio.`, 'WARNING', 'SOLICITUD_RECHAZADA', { refInicio: objetivo.s.toISOString(), tocadas });
    const copia = vista.find((b) => b.id === c.id);
    const dest = reubicar(copia, vista, []);
    if (!dest) return fin('Extensión rechazada', `Extender ${objetivo.sala} desplazaría a ${c.ocupante} y no hay otra sala libre para ${c.asistentes} personas.`, 'WARNING', 'SOLICITUD_RECHAZADA', { refInicio: objetivo.s.toISOString(), tocadas });
