  if (riesgo) return fin('Aviso de seguridad registrado', riesgo.texto, 'WARNING', 'NINGUNA', { ops });
  if (!grave) return fin('Incidencia registrada', `Registré tu reporte: «${incidencia.descripcion.slice(0, 120)}». Prioridad ${PRIO[incidencia.prioridad] || incidencia.prioridad}${incidencia.areaResponsable ? `, área ${AREA[incidencia.areaResponsable] || incidencia.areaResponsable}` : ''}. Una persona del equipo lo revisará.`, 'SUCCESS', 'NINGUNA', { ops });
