  const fuera = salas.filter((s) => s.estado !== 'DISPONIBLE').map((s) => s.nombre);
  const libresNombres = l.map((s) => s.nombre);
  const parecidas = (ocupadas.includes('Azul') && libresNombres.includes('Azules')) || (ocupadas.includes('Azules') && libresNombres.includes('Azul'))
    ? ' Ojo: Azul y Azules son salas distintas.'
    : '';
  const extra = `${ocupadas.length ? ` Ocupadas en ese horario: ${ocupadas.join(', ')}.` : ''}${fuera.length ? ` Fuera de servicio: ${fuera.join(', ')}.` : ''}${parecidas}`;
  return fin('Salas disponibles', `Libres ${diaTxt()} de ${rango(iv)}: ${lista}.${extra}`, 'SUCCESS', 'NINGUNA', {
    refInicio: iv.s.toISOString(),
    detalle: { tipo: 'SALAS_LIBRES', inicio: iv.s.toISOString(), fin: iv.e.toISOString(), asistentes: pedido.asistentes || null, salas: l.map((s) => ({ nombre: s.nombre, capacidad: s.capacidad })), ocupadas, fuera, nota: parecidas.trim() || null },
  });
}

function conversar() {
  const nombre = req.usuario;
  const rolTxt = { DOCENTE: 'docente', COMERCIAL: 'comercial', ADMINISTRATIVO: 'administrativo' }[req.rol] || '';
  const ayuda = 'Puedo ayudarte con las salas: reservar ("Reserva la sala Azul hoy de 3 a 5 pm para 2 personas"), ver qué hay libre ("¿Qué salas hay libres hoy de 2 a 4 pm?"), extender un horario ("Mi clase en Cosmos se extiende hasta las 11:30") y reportar un problema ("El proyector de Skilab no funciona").';
