    const f = new Date(d.getTime() - BOGOTA).toISOString().slice(0, 10);
    return f === hoy ? 'hoy' : `el ${f.slice(8, 10)}/${f.slice(5, 7)}`;
  };
  const proximas = () => reservas.filter((b) => norm(b.ocupante) === norm(nombre) && b.e > ahora).sort((a, b) => a.s - b.s).slice(0, 5);
  if (charla === 'MENU') return fin('Menú', MENU, 'SUCCESS', 'NINGUNA');
  if (charla === 'OPCION_1') return fin('Reservar una sala', 'Envíame en un solo mensaje la sala, el día, la hora de inicio y fin y cuántas personas. Ejemplo: «Reserva la sala Azul mañana de 3 a 5 pm para 2 personas». Si no sabes qué sala, dime solo el horario y los asistentes y elijo la más ajustada.', 'SUCCESS', 'NINGUNA');
  if (charla === 'OPCION_2') return fin('Reportar una incidencia', 'Cuéntame en un solo mensaje qué ocurre y en qué sala. Ejemplo: «El proyector de Skilab no funciona». Si hay peligro real, llama al 123.', 'SUCCESS', 'NINGUNA');
  if (charla === 'OPCION_3') return fin('Ver salas libres', 'Dime el día y el horario. Ejemplo: «¿Qué salas hay libres hoy de 2 a 4 pm?»', 'SUCCESS', 'NINGUNA');
  if (charla === 'OPCION_4') {
    const mias = proximas();
    return fin('Mis reservas', mias.length ? `Tus próximas reservas: ${mias.map((b) => `${b.sala} ${etiqueta(b.s)} de ${rango(b)}`).join('; ')}.` : 'No tienes reservas próximas a tu nombre.', 'SUCCESS', 'NINGUNA');
  }
  if (charla === 'IDENTIDAD') {
    const mias = proximas();
    const lista = mias.length ? ` Tus próximas reservas: ${mias.map((b) => `${b.sala} ${etiqueta(b.s)} de ${rango(b)}`).join('; ')}.` : ' No tienes reservas próximas a tu nombre.';
    return fin('Tu perfil', quien ? `Te veo como ${quien}${rolTxt ? `, solicitante ${rolTxt}` : ''}. Es el nombre de tu perfil de WhatsApp; no está verificado.${lista}` : `Estás identificado con tu sesión de CampusFlow.${lista}`, 'SUCCESS', 'NINGUNA');
  }
  if (charla === 'GRACIAS') return fin('¡Con gusto!', 'Aquí estoy cuando necesites reservar, consultar una sala o reportar un problema.', 'SUCCESS', 'NINGUNA');
  if (charla === 'SALUDO') return fin(quien ? `¡Hola, ${quien}!` : '¡Hola!', `Soy el asistente de agenda de CampusFlow.\n${MENU}`, 'SUCCESS', 'NINGUNA');
  if (charla === 'BOT') return fin('Soy el asistente de agenda de CampusFlow', `Uso IA para entender tu mensaje y reglas fijas para decidir.\n${MENU}\nTambién puedes escribirme directo, por ejemplo: «Reserva la sala Azul hoy de 3 a 5 pm para 2 personas».`, 'SUCCESS', 'NINGUNA');
  return fin('Cómo puedo ayudarte', `${charla === 'AYUDA' ? '' : 'No tengo claro qué necesitas. '}\n${MENU}`, 'SUCCESS', 'NINGUNA');
}

function fueraDeAlcance() {
  return fin('Mensaje fuera de este chat', 'Este mensaje no corresponde a este chat. Aquí solo gestiono las salas del campus (reservar, ver disponibilidad, extender un horario) y las incidencias reales de los espacios. Por ejemplo: "Reserva la sala Azul hoy de 3 a 5 pm para 2 personas". No registré nada.', 'WARNING', 'NINGUNA');
}
const manejadores = { RESERVA: reservar, EXTENSION: extender, INCIDENCIA: incidente, CONSULTA: consultar, CONVERSACION: conversar, FUERA_DE_ALCANCE: fueraDeAlcance };
// Modo PROPUESTA: se calcula todo igual pero NO se escribe nada (el plan queda vacío y se informa como propuesta).
const salidaFinal = dia < hoy
  ? fin('Fecha pasada', `El ${dia.slice(8, 10)}/${dia.slice(5, 7)} ya pasó. Indica hoy o un día futuro.`, 'WARNING', 'SOLICITUD_RECHAZADA')
  : salaDesconocida && ['RESERVA', 'CONSULTA', 'EXTENSION'].includes(ia.intencion)
    ? fin('Sala no encontrada', `No existe una sala llamada «${salaDesconocida}». Salas del campus: ${[...salas].sort((a, b) => a.capacidad - b.capacidad).map((s) => s.nombre).join(', ')}.`, 'WARNING', 'SOLICITUD_RECHAZADA')
    : manejadores[ia.intencion]();
const o = salidaFinal[0].json;
o.ejecucion = o.plan.ops.length ? 'APLICADA' : 'SIN_CAMBIOS';
if (propuesta) {
  o.propuesta = o.plan.ops;
  o.plan = { ops: [] };
  o.ejecucion = 'NO_APLICADA';
  o.decisionIA.titulo = 'Propuesta · ' + o.decisionIA.titulo;
  o.decisionIA.explicacion = 'Propuesta sin aplicar: ' + o.decisionIA.explicacion;
  o.decisionIA.accionEjecutada = 'PROPUESTA_' + o.decisionIA.accionEjecutada;
}
// Tras una gestión terminada, por WhatsApp se ofrece otra actividad con el menú (no si faltan datos ni en emergencias).
const sinMenu = riesgo || /^(Faltan datos|Falta la|Indica el horario|Fecha pasada|Horario inválido|Horario pasado)/.test(o.decisionIA.titulo.replace(/^Propuesta · /, ''));
if (req.canal === 'whatsapp' && !sinMenu && ['RESERVA', 'EXTENSION', 'INCIDENCIA', 'CONSULTA', 'FUERA_DE_ALCANCE'].includes(ia.intencion)) {
  o.decisionIA.explicacion += `\n\n${OTRA}`;
}
return salidaFinal;

// Construye la respuesta del contrato con el estado REAL leído de la base tras aplicar el plan.
const m = $('Motor de Reglas').first().json;
const estado = $('Leer Estado Final').first().json.estado;
let fallo = null;
try { const a = $('Aplicar Plan').first().json; if (a && a.error) fallo = a.error; } catch (e) { fallo = null; }

const BOGOTA = 5 * 3600e3;
const hhmm = (iso) => new Date(new Date(iso).getTime() - BOGOTA).toISOString().slice(11, 16);
const ref = new Date(m.refInicio || estado.now);
const reservas = estado.bookings || [];
const salas = estado.rooms.map((s) => {
  const propias = reservas.filter((b) => b.sala === s.nombre);
  const tocada = propias.find((b) => m.tocadas.some((t) => t.sala === s.nombre && t.ocupante === b.ocupante));
  const activa = propias.find((b) => new Date(b.inicio) <= ref && ref < new Date(b.fin));
  const b = tocada || activa;
  const base = { nombre: s.nombre, capacidad: s.capacidad };
  if (s.estado === 'MANTENIMIENTO') return { ...base, estado: 'MANTENIMIENTO', ocupanteActual: null, horario: null, nota: 'Inhabilitada por incidencia' };
  if (s.estado === 'DESHABILITADA') return { ...base, estado: 'MANTENIMIENTO', ocupanteActual: null, horario: null, nota: 'Sin habilitar por el operador' };
  if (!b) return { ...base, estado: 'DISPONIBLE', ocupanteActual: null, horario: null, nota: null };
  return { ...base, estado: b.reubicado_desde ? 'REUBICADO_IA' : 'OCUPADO', ocupanteActual: b.ocupante, horario: `${hhmm(b.inicio)} - ${hhmm(b.fin)}`, nota: b.nota || null };
});

let decisionIA = m.decisionIA;
let httpStatus = m.httpStatus;
let status = m.status;
if (fallo) {
  decisionIA = { titulo: 'No se pudo aplicar el cambio', explicacion: 'Otra solicitud ocupó el espacio al mismo tiempo; no se modificó nada. Vuelve a intentarlo.', tipoAlerta: 'ERROR', accionEjecutada: 'SOLICITUD_RECHAZADA' };
  httpStatus = 409;
  status = 'error';
}
const ejecucion = fallo ? 'SIN_CAMBIOS' : (m.ejecucion || 'SIN_CAMBIOS');
const respuesta = { status, decisionIA, ejecucion, interpretacionIA: m.interpretacionIA, salas, incidenciaDetectada: m.incidenciaDetectada };
// WhatsApp solo admite *negrita*, _cursiva_, listas «- » y saltos de línea: se arma un mensaje propio
// con el detalle estructurado del Motor. La respuesta del frontend (respuesta) no cambia.
function mensajeWhatsApp() {
  const ICONO = { SUCCESS: '✅', WARNING: '⚠️', ERROR: '❌' };
  const local = (iso) => new Date(new Date(iso).getTime() - BOGOTA);
  const hora = (iso) => {
    const d = local(iso);
    const h = d.getUTCHours();
    return `${h % 12 || 12}:${String(d.getUTCMinutes()).padStart(2, '0')} ${h < 12 ? 'a. m.' : 'p. m.'}`;
  };
  const horaCorta = (iso) => {
    const d = local(iso);
    const h = d.getUTCHours();
    const mm = d.getUTCMinutes();
    return `${h % 12 || 12}${mm ? `:${String(mm).padStart(2, '0')}` : ''} ${h < 12 ? 'am' : 'pm'}`;
  };
  const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const dia = (iso) => {
    const d = local(iso);
    const f = d.toISOString().slice(0, 10);
    const hoy = local(estado.now).toISOString().slice(0, 10);
    const manana = new Date(local(estado.now).getTime() + 86400e3).toISOString().slice(0, 10);
    if (f === hoy) return 'Hoy';
    if (f === manana) return 'Mañana';
    const n = DIAS[d.getUTCDay()];
    return `${n[0].toUpperCase()}${n.slice(1)} ${d.getUTCDate()} de ${MESES[d.getUTCMonth()]}`;
  };
  const personas = (n) => `${n} ${n === 1 ? 'persona' : 'personas'}`;
  const lista = (l) => l.map((s) => `- ${s.nombre} · ${personas(s.capacidad)}`).join('\n');
  const explicacion = decisionIA.explicacion.replace(/^Propuesta sin aplicar: /, '');
  // El Motor añade el menú al final por WhatsApp; se conserva al final del mensaje formateado.
  const corte = explicacion.indexOf('¿Quieres hacer otra actividad?');
  const menu = corte >= 0 ? `\n\n${explicacion.slice(corte)}` : '';
  const base = (corte >= 0 ? explicacion.slice(0, corte) : explicacion).trim();
  const titulo = decisionIA.titulo.replace(/^Propuesta · /, '');
  const cabecera = `${ICONO[decisionIA.tipoAlerta] || 'ℹ️'} *${titulo}*`;
  const nota = ejecucion === 'NO_APLICADA' ? '\n\n_Es una propuesta: no se aplicó ningún cambio._' : '';
  const d = fallo ? null : m.detalle;

  if (d && d.tipo === 'SALAS_LIBRES') {
    const cuando = `🕒 ${dia(d.inicio)}, ${hora(d.inicio)} – ${hora(d.fin)}`;
    const otras = [
      d.ocupadas && d.ocupadas.length ? `_Ocupadas en ese horario:_ ${d.ocupadas.join(', ')}` : '',
      d.fuera && d.fuera.length ? `_Fuera de servicio:_ ${d.fuera.join(', ')}` : '',
      d.nota ? `_${d.nota}_` : '',
    ].filter(Boolean).join('\n');
    if (!d.salas.length) {
      return `⚠️ *Sin salas disponibles*\n${cuando}\n\nNo hay salas libres${d.asistentes ? ` para ${personas(d.asistentes)}` : ''} en ese horario. Prueba con otra hora.${otras ? `\n\n${otras}` : ''}${nota}${menu}`;
    }
    const grupos = [
      ['Pequeñas (hasta 12)', d.salas.filter((s) => s.capacidad <= 12)],
      ['Medianas (13 a 40)', d.salas.filter((s) => s.capacidad > 12 && s.capacidad <= 40)],
      ['Grandes (más de 40)', d.salas.filter((s) => s.capacidad > 40)],
    ].filter(([, l]) => l.length);
    const cuerpo = grupos.map(([g, l]) => `*${g}*\n${lista(l)}`).join('\n\n');
    const ejemplo = `Reserva la sala ${d.salas[0].nombre} ${dia(d.inicio).toLowerCase()} de ${horaCorta(d.inicio)} a ${horaCorta(d.fin)} para ${personas(d.asistentes || 2)}`;
    return `${cabecera}\n${cuando}\n\n${cuerpo}${otras ? `\n\n${otras}` : ''}\n\n_Para reservar escribe, por ejemplo:_\n«${ejemplo}»${nota}${menu}`;
  }
  if (d && d.tipo === 'RESERVA') {
    return `${cabecera}\n\n🏢 Sala *${d.sala}* (${personas(d.capacidad)})\n📅 ${dia(d.inicio)}\n🕒 ${hora(d.inicio)} – ${hora(d.fin)}\n👥 ${d.asistentes} ${d.asistentes === 1 ? 'asistente' : 'asistentes'}${nota}${menu}`;
  }
  // Resto de casos: una frase por línea; las alternativas, como lista; los ejemplos, en su propia línea.
  let cuerpo = base;
  let extra = '';
  if (d && d.tipo === 'ALTERNATIVAS' && d.salas.length) {
    cuerpo = cuerpo.replace(/\s*(Alternativas|Libres en ese horario): [^]*$/, '');
    extra = `\n\n*Alternativas libres*\n${lista(d.salas)}`;
  }
  // Primero se separan las frases (solo tras espacios) y después los ejemplos, para no perder líneas en blanco.
  cuerpo = cuerpo
    .replace(/\.[ ]+(?=[A-ZÁÉÍÓÚÑ¿¡«"])/g, '.\n')
    .replace(/,? por ejemplo: "([^"]+)"\.?/g, '.\n\n_Por ejemplo:_\n«$1»')
    .replace(/,? por ejemplo: «([^»]+)»\.?/g, '.\n\n_Por ejemplo:_\n«$1»')
    .replace(/\n?Ejemplo: «([^»]+)»\.?[ ]*/g, '\n\n_Por ejemplo:_\n«$1»\n\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return `${cabecera}\n\n${cuerpo}${extra}${nota}${menu}`;
}
const texto = mensajeWhatsApp();
return [{ json: { canal: m.canal, replyTo: m.replyTo, httpStatus, respuesta, texto } }];
